#include "resident/kernel/catalog_section_observation.hpp"
// 真实会面节点和双方身份只读核验；来源有效不等于当前仍可办理婚姻。
#include "marriage_source.hpp"
#include "resident/storage/common_store.hpp"
#include "resident/domains/interaction/face_to_face_contact.hpp"
#include <algorithm>
#include <set>
#include <tuple>
namespace hanmo::resident { namespace {
// 所有引用有有限长度；未知空值不能被当作开放许可。
bool id(const StableId& value){return !value.empty()&&value.size()<=256;}
// 只从同一正式目录读取指定对白，不能用自由文本冒本人意愿。
const DialogueDefinition* dialogue(const InteractionCatalog& c,const StableId& name){for(const auto& d:c.dialogues)if(d.id==name)return &d;return nullptr;}
// 指定节点必须实际存在；不同对白的同名节点不共享许可。
const DialogueNode* node(const DialogueDefinition& d,const StableId& name){for(const auto& n:d.nodes)if(n.id==name)return &n;return nullptr;}
// 比较全部会面语义字段，不用field_order决定业务相等。
bool context_equal(const InteractionContext& a,const InteractionContext& b){return std::tie(a.place_id,a.provider_actor_id,a.role_id,a.kind,a.encounter_id,a.input_error)==std::tie(b.place_id,b.provider_actor_id,b.role_id,b.kind,b.encounter_id,b.input_error);}
// 明确18岁门，先限时钟范围再相减，未知生日及未来来源均拒绝。
Status adult_at(const CommonState& c,const StableId& actor,Integer tick){const auto* a=c.actors.find(actor);constexpr Integer maximum=2147483647;if(!a)return common_failure("UnknownMarriageActor",actor);if(tick<0||tick>c.identity.tick||tick>maximum||!a->birth_tick||*a->birth_tick< -maximum||*a->birth_tick>tick)return common_failure("MarriageAgeUnknown",actor);return tick-*a->birth_tick>=18*720?common_success():common_failure("MarriageRequiresAdult",actor);}
}
bool marriage_statement_equal(const MarriageStatementSource& a,const MarriageStatementSource& b){return std::tie(a.statement_id,a.speaker_actor_id,a.listener_actor_id,a.dialogue_id,a.node_id,a.node_kind,a.intent,a.session_id,a.scenario_id,a.world_id,a.terms_version,a.tick,a.revision,a.speaker_birth_tick,a.listener_birth_tick)==std::tie(b.statement_id,b.speaker_actor_id,b.listener_actor_id,b.dialogue_id,b.node_id,b.node_kind,b.intent,b.session_id,b.scenario_id,b.world_id,b.terms_version,b.tick,b.revision,b.speaker_birth_tick,b.listener_birth_tick)&&context_equal(a.context,b.context);}
Status validate_marriage_source_catalog(const MarriageSourceCatalog& c,const CommonCatalog& shared,const InteractionCatalog& interactions){
  // 只旁观本次原入口；返回值与首错仍由原函数独占。
  ::hanmo::resident::catalog_section_observation::Scope catalog_cost_observation(
      ::hanmo::resident::catalog_section_observation::Kind::catalog_validation, 38, "MarriageSourceCatalog", "validate_marriage_source_catalog", &c);

    if(!c.enabled)return c.origins.empty()&&c.statements.empty()?common_success():common_failure("MarriageProfileRequired");
    if(c.origins.empty()||c.origins.size()>4096||c.statements.empty()||c.statements.size()>4096)return common_failure("InvalidMarriageCatalogSize");
    auto known=[&](const StableId& actor){return id(actor)&&std::find(shared.actor_ids.begin(),shared.actor_ids.end(),actor)!=shared.actor_ids.end();};
    for(const auto& row:c.origins.rows()){const auto& origin=row.second;if(row.first!=origin.actor_id||!known(origin.actor_id)||(origin.status!="unknown"&&origin.status!="unmarried"&&origin.status!="married"))return common_failure("InvalidMarriageOrigin",row.first);if((origin.status=="married")!=bool(origin.spouse_actor_id))return common_failure("InvalidMarriageOriginSpouse",row.first);if(origin.spouse_actor_id){const auto* other=c.origins.find(*origin.spouse_actor_id);if(*origin.spouse_actor_id==origin.actor_id||!known(*origin.spouse_actor_id)||!other||other->status!="married"||other->spouse_actor_id!=std::optional<StableId>{origin.actor_id})return common_failure("MarriageOriginNotReciprocal",row.first);}}
    std::set<std::tuple<StableId,StableId,StableId,StableId>> bindings;
    for(const auto& row:c.statements.rows()){const auto& s=row.second;for(const auto* value:{&s.id,&s.speaker_actor_id,&s.listener_actor_id,&s.dialogue_id,&s.node_id})if(!id(*value))return common_failure("InvalidMarriageStatement",row.first);if(row.first!=s.id||s.terms_version!=1||s.speaker_actor_id==s.listener_actor_id||(s.intent!="offer_marriage"&&s.intent!="accept_dissolution"))return common_failure("InvalidMarriageStatementScope",row.first);if(!known(s.speaker_actor_id)||!known(s.listener_actor_id)||!c.origins.find(s.speaker_actor_id)||!c.origins.find(s.listener_actor_id))return common_failure("MarriageOriginRequired",row.first);const auto* d=dialogue(interactions,s.dialogue_id);const auto* n=d?node(*d,s.node_id):nullptr;if(!d||!shared.roles.find(d->context_role)||!n||(n->kind!="say"&&n->kind!="choice"))return common_failure("MarriageOrdinaryDialogueRequired",row.first);if(!bindings.emplace(s.speaker_actor_id,s.listener_actor_id,s.dialogue_id,s.node_id).second)return common_failure("DuplicateMarriageStatementBinding",row.first);}
    return common_success();
}
Status validate_marriage_statement_source(const CommonState& c,const CommonCatalog& shared,const InteractionCatalog& interactions,const MarriageSourceCatalog& catalog,const MarriageStatementSource& s){
    if(!catalog.enabled)return common_failure("MarriageProfileRequired");auto checked=validate_marriage_source_catalog(catalog,shared,interactions);if(!checked.ok)return checked;const auto* d=catalog.statements.find(s.statement_id);if(!d||std::tie(d->speaker_actor_id,d->listener_actor_id,d->dialogue_id,d->node_id,d->intent,d->terms_version)!=std::tie(s.speaker_actor_id,s.listener_actor_id,s.dialogue_id,s.node_id,s.intent,s.terms_version))return common_failure("MarriageStatementBindingMismatch");
    if(s.world_id!=c.identity.world_id||s.scenario_id!=c.metadata.scenario_id||!id(s.scenario_id)||std::all_of(s.world_id.begin(),s.world_id.end(),[](auto b){return b==0;}))return common_failure("MarriageStatementWorldMismatch");if(s.revision<0||s.revision>c.identity.revision)return common_failure("MarriageStatementTimeMismatch");const auto* talk=dialogue(interactions,s.dialogue_id);const auto* saying=node(*talk,s.node_id);const auto* role=shared.roles.find(talk->context_role);if(!id(s.session_id)||s.node_kind!=saying->kind||!face_to_face_contact_context_valid(s.context)||s.context.kind||s.context.provider_actor_id!=s.speaker_actor_id||s.context.role_id!=talk->context_role||s.context.place_id!=role->place_id||!shared.places.find(s.context.place_id))return common_failure("MarriageStatementContactMismatch");for(const auto* actor:{&s.speaker_actor_id,&s.listener_actor_id}){checked=adult_at(c,*actor,s.tick);if(!checked.ok)return checked;}if(s.speaker_birth_tick!=*c.actors.find(s.speaker_actor_id)->birth_tick||s.listener_birth_tick!=*c.actors.find(s.listener_actor_id)->birth_tick)return common_failure("MarriageStatementIdentityChanged");return common_success();
}
Outcome<MarriageStatementQuote> preview_marriage_statement(const CommonStore& c,const InteractionState& meeting,const InteractionCatalog& interactions,const InteractionAccess& access,const MarriageSourceCatalog& catalog,const StableId& listener,const StableId& statement){
    if(listener.empty()||listener!=c.state().metadata.player_actor_id)return {false,{},common_failure("MarriageListenerAuthorityRequired").error};if(!interactions.common)return {false,{},common_failure("MarriageCommonCatalogRequired").error};auto checked=validate_marriage_source_catalog(catalog,*interactions.common,interactions);if(!checked.ok)return {false,{},checked.error};const auto* definition=catalog.statements.find(statement);if(!catalog.enabled||!definition||definition->listener_actor_id!=listener)return {false,{},common_failure("MarriageStatementUnavailable").error};for(const auto* actor:{&listener,&definition->speaker_actor_id}){checked=adult_at(c.state(),*actor,c.tick());if(!checked.ok)return {false,{},checked.error};}
    auto proof=preview_authored_node_source(c,meeting,interactions,access,listener,definition->speaker_actor_id);if(!proof.ok)return {false,{},proof.error};if(proof.value.dialogue_id!=definition->dialogue_id||proof.value.node_id!=definition->node_id)return {false,{},common_failure("MarriageStatementNotCurrent").error};MarriageStatementSource s;s.statement_id=definition->id;s.speaker_actor_id=definition->speaker_actor_id;s.listener_actor_id=listener;s.dialogue_id=definition->dialogue_id;s.node_id=definition->node_id;s.node_kind=proof.value.node_kind;s.intent=definition->intent;s.terms_version=definition->terms_version;s.session_id=proof.value.session_id;s.scenario_id=c.state().metadata.scenario_id;s.world_id=c.state().identity.world_id;s.context=proof.value.context;s.tick=c.tick();s.revision=c.state().identity.revision;s.speaker_birth_tick=*c.state().actors.find(s.speaker_actor_id)->birth_tick;s.listener_birth_tick=*c.state().actors.find(listener)->birth_tick;checked=validate_marriage_statement_source(c.state(),*interactions.common,interactions,catalog,s);return checked.ok?Outcome<MarriageStatementQuote>{true,{proof.value,std::move(s)},{}}:Outcome<MarriageStatementQuote>{false,{},checked.error};
}
Status revalidate_marriage_statement(const CommonStore& c,const InteractionState& meeting,const InteractionCatalog& interactions,const InteractionAccess& access,const MarriageSourceCatalog& catalog,const MarriageStatementQuote& quote){const auto& a=quote.statement;const auto& p=quote.source;if(std::tie(p.actor_id,p.provider_actor_id,p.dialogue_id,p.node_id,p.node_kind,p.session_id,p.source_identity.world_id,p.source_identity.tick,p.source_identity.revision)!=std::tie(a.listener_actor_id,a.speaker_actor_id,a.dialogue_id,a.node_id,a.node_kind,a.session_id,a.world_id,a.tick,a.revision)||!context_equal(p.context,a.context))return common_failure("MarriageStatementSourceMismatch");auto checked=revalidate_authored_node_source(c,meeting,interactions,access,p);if(!checked.ok)return checked;auto current=preview_marriage_statement(c,meeting,interactions,access,catalog,a.listener_actor_id,a.statement_id);if(!current.ok)return {false,{},current.error};return marriage_statement_equal(a,current.value.statement)?common_success():common_failure("StaleMarriageStatement");}
}
